import{_ as a,o as l,c as e,a4 as s}from"./chunks/framework.Co6Rcm-5.js";const k=JSON.parse('{"title":"开发守则","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/development-rules.md","filePath":"appendix/development-rules.md","lastUpdated":1786522313000}'),t={name:"appendix/development-rules.md"};function r(d,i,n,o,h,p){return l(),e("div",null,[...i[0]||(i[0]=[s(`<h1 id="开发守则" tabindex="-1">开发守则 <a class="header-anchor" href="#开发守则" aria-label="Permalink to “开发守则”">​</a></h1><p>这份守则用于约束知识总结站的内容、前端和发布流程。目标是让每次修改都保持范围清楚、视觉一致、可以验证并且容易回退。</p><h2 id="_1-开始开发前" tabindex="-1">1. 开始开发前 <a class="header-anchor" href="#_1-开始开发前" aria-label="Permalink to “1. 开始开发前”">​</a></h2><h3 id="明确四项输入" tabindex="-1">明确四项输入 <a class="header-anchor" href="#明确四项输入" aria-label="Permalink to “明确四项输入”">​</a></h3><p>开始写代码前，先写清楚：</p><ol><li><strong>目标</strong>：用户最终能完成什么事情？</li><li><strong>范围</strong>：允许修改哪些页面、组件和配置？</li><li><strong>约束</strong>：哪些接口、路由、变量或视觉行为不能改变？</li><li><strong>验收</strong>：用什么命令和页面操作证明任务完成？</li></ol><p>如果目标存在多种解释，并且不同解释会产生明显不同的结果，应先确认而不是静默选择。</p><h3 id="先检查来源权利" tabindex="-1">先检查来源权利 <a class="header-anchor" href="#先检查来源权利" aria-label="Permalink to “先检查来源权利”">​</a></h3><p>复刻或整理外部内容时，必须检查许可证、署名要求和素材来源。没有明确许可证时：</p><ul><li>不复制整篇正文、截图和品牌素材。</li><li>可以复刻不受保护的功能结构和通用布局。</li><li>使用独立文字、图形和组件表达总结。</li><li>在页面末尾列出参考链接和实现说明。</li></ul><h2 id="_2-保持最小修改" tabindex="-1">2. 保持最小修改 <a class="header-anchor" href="#_2-保持最小修改" aria-label="Permalink to “2. 保持最小修改”">​</a></h2><ul><li>每一行改动都应能追溯到当前任务。</li><li>不重命名无关变量，不调整无关格式，不顺手清理旧代码。</li><li>不为单一场景提前设计通用框架。</li><li>重复结构出现两次以上，并且确实需要统一维护时，再提取组件。</li><li>删除由本次改动产生的无用导入、样式和文件，但不处理历史遗留代码。</li></ul><h2 id="_3-页面与路由" tabindex="-1">3. 页面与路由 <a class="header-anchor" href="#_3-页面与路由" aria-label="Permalink to “3. 页面与路由”">​</a></h2><ul><li>正式内容全部放在 <code>docs/</code>，目录名和文件名使用小写英文与连字符。</li><li>需要保留尾部斜杠的深层路由时，使用 <code>目录/index.md</code>。</li><li>新增或移动页面时同步更新 <code>docs/.vitepress/config.mts</code> 中的导航和侧栏。</li><li>每个页面必须设置准确的标题与描述；特殊页面通过 <code>pageClass</code> 隔离样式。</li><li>内部链接使用站内路径，不硬编码 GitHub Pages 的 <code>/knowledge-summary/</code> base。</li></ul><h2 id="_4-视觉与组件" tabindex="-1">4. 视觉与组件 <a class="header-anchor" href="#_4-视觉与组件" aria-label="Permalink to “4. 视觉与组件”">​</a></h2><h3 id="站点视觉基线" tabindex="-1">站点视觉基线 <a class="header-anchor" href="#站点视觉基线" aria-label="Permalink to “站点视觉基线”">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>基线</th></tr></thead><tbody><tr><td>顶栏</td><td>固定 64px，高层级但不遮挡正文</td></tr><tr><td>桌面侧栏</td><td>约 272px，紧凑章节列表</td></tr><tr><td>正文</td><td>最大约 760px，14px / 1.75 行距</td></tr><tr><td>页内目录</td><td>1280px 以上常驻，窄屏折叠</td></tr><tr><td>品牌色</td><td>使用 <code>--knowledge-primary</code> 语义令牌，深色模式自动切换为更亮蓝色</td></tr><tr><td>圆角</td><td>卡片 8—12px，控件 6—8px</td></tr><tr><td>响应式</td><td>重点检查 639px、959px、1279px 附近</td></tr></tbody></table><h3 id="组件原则" tabindex="-1">组件原则 <a class="header-anchor" href="#组件原则" aria-label="Permalink to “组件原则”">​</a></h3><ul><li>首选 VitePress 原生标题、表格、提示块、代码块和导航能力。</li><li>章节导读使用 <code>SummaryHero</code>，指标使用 <code>StatGrid</code>；能用 Markdown 表格和列表表达时不新增组件。</li><li>需要展示知识链路时使用 <code>InteractiveFlow</code>，需要做容量估算、方案权衡或拓扑比较时分别使用 <code>CapacityLab</code>、<code>TradeoffExplorer</code>、<code>TopologyExplorer</code>；前端页面不直接展示 Mermaid 源码块。</li><li>估算 Widget 必须同时展示计算假设与适用边界，不能把理论上界伪装成生产测量值。</li><li>交互选项采用 Tabs 或 Toggle Group 的语义结构，支持键盘聚焦，并通过文字而不只通过颜色表达当前状态。</li><li>论文资料按模型、方法与工程主题直接组织；允许重排标题和段落，但原始正文、公式、链接与图片只能增加，不能删减。</li><li>论文图片使用 <code>ZoomableImage</code>，必须保留替代文本，并验证放大、缩小、关闭和移动端视口。</li><li>颜色、边框、圆角、阴影和焦点状态使用 <code>--knowledge-*</code> 语义令牌，不在组件中维护独立色板。</li><li>卡片采用中性表面、细边框和克制阴影，状态通过既有变体与语义色表达。</li><li>组件只负责一种视觉或行为职责，输入通过明确 props 传递。</li><li>不在 Markdown 中堆叠大段重复内联样式。</li><li>页面专属选择器必须带页面类，例如 <code>.knowledge-home</code>。</li></ul><h3 id="可访问性" tabindex="-1">可访问性 <a class="header-anchor" href="#可访问性" aria-label="Permalink to “可访问性”">​</a></h3><ul><li>使用语义化标题层级，不跳过必要层级。</li><li>图片必须提供能说明内容的替代文本。</li><li>按钮必须有可理解的文字或 <code>aria-label</code>。</li><li>不只依靠颜色表达状态；同时提供文字、图标或形状。</li><li>浅色、深色模式都要保持足够对比度和可见焦点。</li></ul><h2 id="_5-内容质量" tabindex="-1">5. 内容质量 <a class="header-anchor" href="#_5-内容质量" aria-label="Permalink to “5. 内容质量”">​</a></h2><ul><li>一篇总结至少包含问题、结论、证据、限制和下一步。</li><li>区分已验证事实、来源观点和作者推断。</li><li>时效性内容标注日期，并优先链接到一手来源。</li><li>代码示例必须足够小，且与正文结论直接相关。</li><li>不使用大段空泛口号替代可执行步骤。</li></ul><h3 id="notion-总结规则" tabindex="-1">Notion 总结规则 <a class="header-anchor" href="#notion-总结规则" aria-label="Permalink to “Notion 总结规则”">​</a></h3><ul><li>先读取父子关系、数据库属性和页面正文，再确定站内分组。</li><li>每篇总结末尾保留 Notion 来源链接，并同步更新来源索引。</li><li>合并重复内容，但不删除或修改原始 Notion 页面。</li><li>只有标题或收藏链接的页面标记为待消化，不补写不存在的结论。</li><li>时效性日报和趋势报告标明快照日期，不作为长期事实直接引用。</li></ul><h2 id="_6-安全与依赖" tabindex="-1">6. 安全与依赖 <a class="header-anchor" href="#_6-安全与依赖" aria-label="Permalink to “6. 安全与依赖”">​</a></h2><ul><li>不把密钥、Cookie、访问令牌、个人信息和生产数据写入仓库。</li><li>外部链接使用 HTTPS；新窗口链接添加 <code>rel=&quot;noreferrer&quot;</code>。</li><li>新增依赖前说明必要性，优先使用现有依赖或浏览器能力。</li><li>用户输入进入 HTML、URL 或命令前必须经过正确的转义或校验。</li><li>高风险功能需要单独的威胁分析、权限边界和失败回退设计。</li></ul><h2 id="_7-运行与验证" tabindex="-1">7. 运行与验证 <a class="header-anchor" href="#_7-运行与验证" aria-label="Permalink to “7. 运行与验证”">​</a></h2><p>所有操作通过脚本完成：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/setup.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 安装依赖</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/dev.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 本地开发</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/check.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 构建与静态产物检查</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/audit.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 依赖安全审计</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/preview.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 预览构建产物</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/deploy.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 发布 GitHub Pages</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>合入前至少完成：</p><ul><li>构建成功，目标深层路由产物存在。</li><li>桌面与移动端无横向溢出。</li><li>浅色与深色模式内容可读。</li><li>侧栏、页内目录、复制按钮和站内链接可用。</li><li>依赖审计没有未解释的高风险问题。</li></ul><h2 id="_8-git-与发布" tabindex="-1">8. Git 与发布 <a class="header-anchor" href="#_8-git-与发布" aria-label="Permalink to “8. Git 与发布”">​</a></h2><ul><li>提交只包含当前任务文件，提交信息使用简洁中文。</li><li>推送前检查工作区和实际 diff，不提交缓存与构建目录。</li><li>发布使用 <code>./scripts/deploy.sh</code>，由脚本构建并更新 <code>gh-pages</code> 分支。</li><li>发布完成后检查 GitHub Pages 状态、线上 HTML、CSS/JS 和每个一级分组至少一个深层路由。</li><li>只有本地产物、远程资源和浏览器可见结果一致时，才能报告上线完成。</li></ul><h2 id="完成定义" tabindex="-1">完成定义 <a class="header-anchor" href="#完成定义" aria-label="Permalink to “完成定义”">​</a></h2><p>任务只有同时满足以下条件才算完成：需求范围内的功能已经实现，构建与审计通过，页面在目标尺寸可用，文档和导航同步更新，线上结果经过实际访问验证，并且不存在未说明的失败或权限问题。</p>`,36)])])}const b=a(t,[["render",r]]);export{k as __pageData,b as default};
